    { id = 4242, title = "Abandoned Hope", level = 54, req = 48, side = "alliance", from = "Marshal Windsor", spot = "Marshal Windsor", turnIn = "Marshal Maxwell", needs = "Marshal Windsor", needsId = 4241, step = 9, of = 9, xp = 5450, goal = "Give Marshal Maxwell the bad news." },
    { id = 4082, title = "KILL ON SIGHT: High Ranking Dark Iron Officials", level = 54, req = 50, side = "horde", from = "KILL ON SIGHT", spot = "KILL ON SIGHT", turnIn = "Warlord Goretooth", needs = "KILL ON SIGHT: Dark Iron Dwarves", needsId = 4081, step = 2, of = 2, xp = 5450, goal = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete." },
    { id = 4241, title = "Marshal Windsor", level = 54, req = 48, side = "alliance", from = "Marshal Maxwell", spot = "Marshal Maxwell", turnIn = "Marshal Windsor", needs = "The True Masters", needsId = 4224, step = 8, of = 8, xp = 5450, goal = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison." },
    { id = 4002, title = "The Eastern Kingdom", level = 54, req = 48, side = "horde", from = "Thrall", spot = "Thrall", turnIn = "Thrall", needs = "What Is Going On?", needsId = 4001, step = 5, of = 5, goal = "Speak with Thrall if you are prepared to take on the mission he has planned." },
    { id = 7201, title = "The Last Element", level = 54, req = 48, side = "horde", from = "Shadowmage Vivian Lagrave", spot = "Shadowmage Vivian Lagrave", turnIn = "Shadowmage Vivian Lagrave", xp = 5450, goal = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals." },
    { id = 4201, title = "The Love Potion", level = 54, req = 50, side = "both", from = "Mistress Nagmara", spot = "Mistress Nagmara", turnIn = "Mistress Nagmara", item = "Nagmara's Vial", xp = 5450, goal = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths." },
    { id = 3982, title = "What Is Going On?", level = 54, req = 48, side = "horde", from = "Commander Gor'shak", spot = "Commander Gor'shak", turnIn = "Commander Gor'shak", needs = "Commander Gor'shak", needsId = 3981, step = 3, of = 3, xp = 4350, goal = "Defend Gor'shak." },
    { id = 4001, title = "What Is Going On?", level = 54, req = 48, side = "horde", from = "Commander Gor'shak", spot = "Commander Gor'shak", turnIn = "Thrall", needs = "What Is Going On?", needsId = 3982, step = 4, of = 4, xp = 550, goal = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby." },
    { id = 4126, title = "Hurley Blackbreath", level = 55, req = 50, side = "alliance", from = "Ragnar Thunderbrew", spot = "Ragnar Thunderbrew", turnIn = "Ragnar Thunderbrew", xp = 5650, goal = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos." },
