    { id = 3907, title = "Disharmony of Fire", level = 56, req = 48, side = "horde", from = "Thunderheart", spot = "Thunderheart", turnIn = "Thunderheart", needs = "Disharmony of Flame", needsId = 3906, step = 2, of = 2, xp = 7300, goal = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart." },
    { id = 4263, title = "Incendius!", level = 56, req = 48, side = "alliance", from = "Jalinda Sprig", spot = "Jalinda Sprig", turnIn = "Jalinda Sprig", needs = "Overmaster Pyron", needsId = 4262, step = 2, of = 2, xp = 5800, goal = "Find Lord Incendius in Blackrock Depths and destroy him!" },
    { id = 4286, title = "The Good Stuff", level = 56, req = 50, side = "alliance", from = "Oralius", spot = "Oralius", turnIn = "Oralius", xp = 5800, goal = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions." },
    { id = 4264, title = "A Crumpled Up Note", level = 58, req = 50, side = "alliance", turnIn = "Marshal Windsor", item = "A Crumpled Up Note", needs = "Abandoned Hope", needsId = 4242, step = 10, of = 10, xp = 6200, goal = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all." },
    { id = 4282, title = "A Shred of Hope", level = 58, req = 50, side = "alliance", from = "Marshal Windsor", spot = "Marshal Windsor", turnIn = "Marshal Windsor", needs = "A Crumpled Up Note", needsId = 4264, step = 11, of = 11, xp = 6200, goal = "Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge." },
    { id = 4024, title = "A Taste of Flame", level = 58, req = 52, side = "both", from = "Cyrus Therepentous", spot = "Cyrus Therepentous", turnIn = "Cyrus Therepentous", item = "Altered Black Dragonflight Molt", needs = "A Taste of Flame", needsId = 4023, step = 2, of = 2, xp = 6200, goal = "Travel to Blackrock Depths and slay Bael'Gar. You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous." },
    { id = 4122, title = "Grark Lorkrub", level = 58, req = 52, side = "horde", from = "Lexlort", spot = "Lexlort", turnIn = "Grark Lorkrub", item = "Thorium Shackles", xp = 6200, goal = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody." },
    { id = 4322, title = "Jail Break!", level = 58, req = 50, side = "alliance", from = "Marshal Windsor", spot = "Marshal Windsor", turnIn = "Marshal Maxwell", needs = "A Shred of Hope", needsId = 4282, step = 12, of = 12, xp = 7750, goal = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed." },
    { id = 4132, title = "Operation: Death to Angerforge", level = 58, req = 52, side = "horde", from = "Warlord Goretooth", spot = "Warlord Goretooth", turnIn = "Warlord Goretooth", needs = "Precarious Predicament", needsId = 4121, step = 3, of = 3, xp = 7750, goal = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete." },
    { id = 4121, title = "Precarious Predicament", level = 58, req = 52, side = "horde", from = "Grark Lorkrub", spot = "Grark Lorkrub", turnIn = "Lexlort", needs = "Grark Lorkrub", needsId = 4122, step = 2, of = 2, xp = 7750, goal = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort." },
    { id = 4063, title = "The Rise of the Machines", level = 58, req = 52, side = "horde", from = "Lotwil Veriatus", spot = "Lotwil Veriatus", turnIn = "Lotwil Veriatus", needs = "The Rise of the Machines", needsId = 4062, step = 3, of = 3, xp = 6200, goal = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic." },
    { id = 4341, title = "Kharan Mighthammer", level = 59, req = 50, side = "alliance", from = "King Magni Bronzebeard", spot = "King Magni Bronzebeard", turnIn = "Kharan Mighthammer", needs = "The Smoldering Ruins of Thaurissan", needsId = 3701, step = 3, of = 3, xp = 5800, goal = "Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison." },
    { id = 4342, title = "Kharan's Tale", level = 59, req = 50, side = "alliance", from = "Kharan Mighthammer", spot = "Kharan Mighthammer", turnIn = "Kharan Mighthammer", xp = 1600, goal = "Listen as Kharan Mighthammer tells his story." },
    { id = 4361, title = "The Bearer of Bad News", level = 59, req = 50, side = "alliance", from = "Kharan Mighthammer", spot = "Kharan Mighthammer", turnIn = "King Magni Bronzebeard", needs = "Kharan Mighthammer", needsId = 4341, step = 4, of = 4, xp = 6400, goal = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard." },
    { id = 4362, title = "The Fate of the Kingdom", level = 59, req = 50, side = "alliance", from = "King Magni Bronzebeard", spot = "King Magni Bronzebeard", turnIn = "Princess Moira Bronzebeard", needs = "The Bearer of Bad News", needsId = 4361, step = 5, of = 5, xp = 8050, goal = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan." },
    { id = 4363, title = "The Princess's Surprise", level = 59, req = 50, side = "alliance", from = "Princess Moira Bronzebeard", spot = "Princess Moira Bronzebeard", turnIn = "King Magni Bronzebeard", needs = "The Fate of the Kingdom", needsId = 4362, step = 6, of = 6, xp = 9650, goal = "Return to Ironforge and speak with King Magni Bronzebeard." },
    { id = 4003, title = "The Royal Rescue", level = 59, req = 48, side = "horde", from = "Thrall", spot = "Thrall", turnIn = "Princess Moira Bronzebeard", needs = "The Eastern Kingdom", needsId = 4002, step = 6, of = 6, xp = 8050, goal = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell." },
    { id = 7604, title = "A Binding Contract", level = 60, req = 60, side = "both", turnIn = "Lokhtos Darkbargainer", item = "Thorium Brotherhood Contract", goal = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron." },
    { id = 9015, title = "The Challenge", level = 60, req = 58, side = "both", from = "Falrin Treeshaper", spot = "Falrin Treeshaper", turnIn = "Anthion Harmon", item = "Banner of Provocation", needs = "The Instigator's Enchantment", needsId = 8950, step = 7, of = 7, xp = 6600, goal = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone. Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet." },
    { id = 4004, title = "The Princess Saved?", level = 60, req = 48, side = "horde", from = "Princess Moira Bronzebeard", spot = "Princess Moira Bronzebeard", turnIn = "Thrall", needs = "The Royal Rescue", needsId = 4003, step = 7, of = 7, xp = 9950, goal = "Return to Thrall!" },
