    { id = 4735, title = "Egg Collection", level = 60, req = 57, side = "both", from = "Tinkee Steamboil", spot = "Tinkee Steamboil", turnIn = "Tinkee Steamboil", item = "Collectronic Module", needs = "Egg Freezing", needsId = 4734, step = 2, of = 2, xp = 9950, goal = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes." },
