    { id = 5081, title = "Maxwell's Mission", level = 60, req = 55, side = "alliance", from = "Marshal Maxwell", spot = "Marshal Maxwell", turnIn = "Marshal Maxwell", needs = "Message to Maxwell", needsId = 5002, step = 3, of = 3, xp = 8550, goal = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done." },
    { id = 4766, title = "Mayara Brightwing", level = 60, req = 57, side = "alliance", from = "Count Remington Ridgewell", spot = "Count Remington Ridgewell", turnIn = "Mayara Brightwing", xp = 650, goal = "Speak with Mayara Brightwing in the Burning Steppes." },
    { id = 4866, title = "Mother's Milk", level = 60, req = 55, side = "both", from = "Ragged John", spot = "Ragged John", turnIn = "Ragged John", xp = 9950, goal = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you." },
    { id = 4742, title = "Seal of Ascension", level = 60, req = 57, side = "both", from = "Vaelan", spot = "Vaelan", turnIn = "Vaelan", xp = 8300, goal = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe." },
    { id = 4768, title = "The Darkstone Tablet", level = 60, req = 57, side = "horde", from = "Shadowmage Vivian Lagrave", spot = "Shadowmage Vivian Lagrave", turnIn = "Shadowmage Vivian Lagrave", xp = 8300, goal = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath." },
