    { id = 8966, title = "The Left Piece of Lord Valthalak's Amulet", level = 60, req = 58, side = "both", from = "Bodley", spot = "Bodley", turnIn = "Bodley", item = "Brazier of Beckoning", needs = "Components of Importance", needsId = 8962, next = "I See Alcaz Island In Your Future...", nextId = 8970, step = 3, of = 4, xp = 8300, goal = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." },
